import { Injectable } from '@nestjs/common';
import {
    registerDecorator,
    ValidationArguments,
    ValidationOptions,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';
import {
    CLOUD_IAM_MISSING_ROLE_MESSAGE,
    CloudIAMInput,
    resolveCloudIAMUpdate,
} from '../../utils/aws/cloudIAM.js';

/**
 * Keeps the reason a given request failed so `defaultMessage` can report it.
 * Keyed on the object being validated so concurrent requests cannot bleed into one another.
 */
const failureReasons = new WeakMap<object, string>();

@ValidatorConstraint({ name: 'ValidCloudIAMRule', async: true })
@Injectable()
export class ValidCloudIAMRule implements ValidatorConstraintInterface {
    async validate(cloudIAM: CloudIAMInput, args: ValidationArguments) {
        try {
            await resolveCloudIAMUpdate(cloudIAM);
            return true;
        } catch (error) {
            if (args?.object) {
                failureReasons.set(args.object, error?.message || CLOUD_IAM_MISSING_ROLE_MESSAGE);
            }
            return false;
        }
    }

    defaultMessage(args: ValidationArguments) {
        return (args?.object && failureReasons.get(args.object)) || CLOUD_IAM_MISSING_ROLE_MESSAGE;
    }
}

export function ValidCloudIAM(validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'ValidCloudIAM',
            target: (object as { constructor: new (...args: unknown[]) => unknown }).constructor,
            propertyName: propertyName,
            constraints: [],
            options: validationOptions,
            validator: ValidCloudIAMRule,
        });
    };
}
