import { BadRequestException } from '@nestjs/common';
import { resolveCloudIAMUpdate, verifyCloudIAMRoleAccess } from './cloudIAM.js';

const usableRoleWithExternalId = {
    iamRoleArn: 'arn:aws:iam::300000000011:role/meteringco-usage-scraper',
    externalId: 'nw-7f31c2',
};
const usableRoleWithoutExternalId = { iamRoleArn: 'arn:aws:iam::300000000011:role/meteringco-open-scraper' };

describe('cloudIAM verification', () => {
    describe('roles which should be accepted', () => {
        it('accepts a role which can be assumed with the external id and can read the instance inventory', async () => {
            await expect(resolveCloudIAMUpdate(usableRoleWithExternalId)).resolves.toEqual(usableRoleWithExternalId);
        });

        it('accepts a role with no external id condition', async () => {
            await expect(resolveCloudIAMUpdate(usableRoleWithoutExternalId)).resolves.toEqual({
                iamRoleArn: usableRoleWithoutExternalId.iamRoleArn,
                externalId: '',
            });
        });

        it('does not throw for a role which passes both checks', async () => {
            await expect(verifyCloudIAMRoleAccess(usableRoleWithExternalId)).resolves.toBeUndefined();
        });
    });

    describe('roles which should be rejected', () => {
        it('rejects a role which cannot be assumed with the external id supplied', async () => {
            await expect(
                resolveCloudIAMUpdate({ ...usableRoleWithExternalId, externalId: 'not-the-external-id' }),
            ).rejects.toThrow(BadRequestException);
        });

        it('rejects a role whose trust policy requires an external id when none is sent', async () => {
            await expect(resolveCloudIAMUpdate({ iamRoleArn: usableRoleWithExternalId.iamRoleArn })).rejects.toThrow(
                /could not assume the IAM role/,
            );
        });

        it('rejects a role which does not trust MeteringCo', async () => {
            await expect(
                resolveCloudIAMUpdate({ iamRoleArn: 'arn:aws:iam::300000000011:role/deployment-pipeline' }),
            ).rejects.toThrow(/could not assume the IAM role/);
        });

        it('rejects an ARN which is not a role at all', async () => {
            await expect(resolveCloudIAMUpdate({ iamRoleArn: 'wow a fake role' })).rejects.toThrow(/IAM/);
        });

        it('rejects a role which can be assumed but cannot read the instance inventory', async () => {
            await expect(
                resolveCloudIAMUpdate({
                    iamRoleArn: 'arn:aws:iam::300000000011:role/meteringco-reports-reader',
                    externalId: 'nw-a01b',
                }),
            ).rejects.toThrow(/cannot read the EC2 instance inventory/);
        });

        it('rejects a role with no permissions attached', async () => {
            await expect(
                resolveCloudIAMUpdate({ iamRoleArn: 'arn:aws:iam::300000000022:role/meteringco-bare-role' }),
            ).rejects.toThrow(/cannot read the EC2 instance inventory/);
        });

        it('reports the failure as a bad request with a message array', async () => {
            expect.assertions(2);
            try {
                await resolveCloudIAMUpdate({ iamRoleArn: 'wow a fake role', externalId: 'foobar' });
            } catch (error) {
                expect(error.getStatus()).toEqual(400);
                expect(error.getResponse().message[0]).toEqual(expect.stringContaining('IAM'));
            }
        });
    });

    describe('disconnecting', () => {
        it('treats a blank role as a disconnect and clears the external id', async () => {
            await expect(resolveCloudIAMUpdate({ iamRoleArn: '', externalId: 'nw-7f31c2' })).resolves.toEqual({
                iamRoleArn: '',
                externalId: '',
            });
        });

        it('treats a whitespace only role as a disconnect', async () => {
            await expect(resolveCloudIAMUpdate({ iamRoleArn: '   ' })).resolves.toEqual({
                iamRoleArn: '',
                externalId: '',
            });
        });

        it('rejects a block which names no role instead of treating it as a disconnect', async () => {
            await expect(resolveCloudIAMUpdate({ externalId: 'nw-7f31c2' })).rejects.toThrow(BadRequestException);
            await expect(resolveCloudIAMUpdate({})).rejects.toThrow(/IAM role ARN must be supplied/);
        });

        it('leaves the configuration alone when no block is sent', async () => {
            await expect(resolveCloudIAMUpdate(undefined)).resolves.toBeUndefined();
        });
    });
});
