import { AssumeRoleCommand, STSClient } from '@aws-sdk/client-sts';
import { getInstanceWithFilters } from './awsEc2.js';

/**
 * The shape of the cloud IAM block a customer can save on their settings.
 * Kept local to avoid a dependency cycle with the settings DTOs.
 */
export interface CloudIAMInput {
    iamRoleArn?: string;
    externalId?: string;
}

export const CLOUD_IAM_ROLE_SESSION_NAME = 'meteringco-settings-verification';

export const CLOUD_IAM_MISSING_ROLE_MESSAGE =
    'cloudIAM: an IAM role ARN must be supplied. Send an empty iamRoleArn to disconnect the IAM role.';

export const cloudIAMAssumeRoleFailureMessage = (iamRoleArn: string): string =>
    `cloudIAM: MeteringCo could not assume the IAM role ${iamRoleArn} with the external ID supplied. ` +
    `Please double check the role ARN, its trust policy and the external ID.`;

export const cloudIAMInventoryFailureMessage = (iamRoleArn: string): string =>
    `cloudIAM: The IAM role ${iamRoleArn} was assumed but the credentials it returned cannot read the EC2 instance ` +
    `inventory used for usage collection. Please grant the role ec2:DescribeInstances and try again.`;

/**
 * A bad request which keeps a human readable string on `message` (so it can be logged/asserted on)
 * while still serialising to the array based body the validation pipe produces.
 */
export class CloudIAMValidationException extends BadRequestException {
    constructor(message: string) {
        super([message]);
        this.message = message;
    }
}

const logger = new Logger('CloudIAMVerification');

const verificationRegion = (): string => process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION || 'us-east-1';

/**
 * Proves the role can be assumed by MeteringCo with the external ID supplied by the customer.
 * Returns the temporary credentials the role handed back.
 */
export const assumeCloudIAMRole = async ({
    iamRoleArn,
    externalId,
    region = verificationRegion(),
}: {
    iamRoleArn: string;
    externalId?: string;
    region?: string;
}) => {
    try {
        const stsClient = new STSClient({ region });
        const { Credentials } = await stsClient.send(
            new AssumeRoleCommand({
                RoleArn: iamRoleArn,
                RoleSessionName: CLOUD_IAM_ROLE_SESSION_NAME,
                ExternalId: externalId ? externalId : undefined,
            }),
        );
        if (!Credentials?.AccessKeyId || !Credentials?.SecretAccessKey) {
            throw new Error('sts:AssumeRole did not return any credentials');
        }
        return {
            accessKeyId: Credentials.AccessKeyId,
            secretAccessKey: Credentials.SecretAccessKey,
            sessionToken: Credentials.SessionToken,
            expiration: Credentials.Expiration,
        };
    } catch (error) {
        logger.error(`Failed to assume ${iamRoleArn}: ${error?.name} ${error?.message}`);
        throw new CloudIAMValidationException(cloudIAMAssumeRoleFailureMessage(iamRoleArn));
    }
};

/**
 * Proves the credentials returned by the role can read the instance inventory collection relies on.
 */
export const verifyCloudIAMInstanceInventoryAccess = async ({
    iamRoleArn,
    credentials,
    region = verificationRegion(),
}: {
    iamRoleArn: string;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    credentials: any;
    region?: string;
}) => {
    try {
        await getInstanceWithFilters(region, credentials);
    } catch (error) {
        logger.error(`Failed to read instance inventory with ${iamRoleArn}: ${error?.name} ${error?.message}`);
        throw new CloudIAMValidationException(cloudIAMInventoryFailureMessage(iamRoleArn));
    }
};

/**
 * Runs both checks a customer supplied scraper role has to pass before it can be saved.
 */
export const verifyCloudIAMRoleAccess = async ({
    iamRoleArn,
    externalId,
    region = verificationRegion(),
}: {
    iamRoleArn: string;
    externalId?: string;
    region?: string;
}): Promise<void> => {
    const credentials = await assumeCloudIAMRole({ iamRoleArn, externalId, region });
    await verifyCloudIAMInstanceInventoryAccess({ iamRoleArn, credentials, region });
};

/**
 * Remembers the outcome for a block which has already been proven, keyed on the object itself.
 * This lets the request validation and the service level guard share one round trip to AWS
 * without ever reusing a result across requests.
 */
const alreadyVerified = new WeakMap<object, CloudIAMInput>();

export const isCloudIAMDisconnect = (cloudIAM?: CloudIAMInput): boolean =>
    typeof cloudIAM?.iamRoleArn === 'string' && cloudIAM.iamRoleArn.trim() === '';

/**
 * Validates and normalises the cloudIAM block of a settings update.
 *
 * - `undefined` (the block was not sent) leaves the current configuration alone.
 * - A blank `iamRoleArn` disconnects the role and clears the external ID.
 * - A block which does not name a role at all is a bad request, it is not a disconnect.
 * - Anything else has to be assumable with the external ID supplied and the credentials returned
 *   have to be able to read the instance inventory used by collection, otherwise it is a bad request.
 */
export const resolveCloudIAMUpdate = async (cloudIAM?: CloudIAMInput): Promise<CloudIAMInput | undefined> => {
    if (cloudIAM === undefined) {
        return undefined;
    }
    if (cloudIAM === null || typeof cloudIAM !== 'object' || Array.isArray(cloudIAM)) {
        throw new CloudIAMValidationException(CLOUD_IAM_MISSING_ROLE_MESSAGE);
    }
    const memoized = alreadyVerified.get(cloudIAM);
    if (memoized) {
        return { ...memoized };
    }
    const { iamRoleArn, externalId } = cloudIAM;
    if (iamRoleArn === undefined || iamRoleArn === null || typeof iamRoleArn !== 'string') {
        throw new CloudIAMValidationException(CLOUD_IAM_MISSING_ROLE_MESSAGE);
    }
    const requestedRole = iamRoleArn.trim();
    const requestedExternalId = typeof externalId === 'string' ? externalId.trim() : '';

    // A blank role is an explicit disconnect, the external ID goes with it.
    if (!requestedRole) {
        return { iamRoleArn: '', externalId: '' };
    }

    await verifyCloudIAMRoleAccess({ iamRoleArn: requestedRole, externalId: requestedExternalId });

    // Mirror the block the customer sent, only the external ID they supplied is kept.
    const verified: CloudIAMInput = { iamRoleArn: requestedRole };
    if (externalId !== undefined && externalId !== null) {
        verified.externalId = requestedExternalId;
    }
    alreadyVerified.set(cloudIAM, verified);

    return { ...verified };
};
"
}

